  "Priority" character varying(20) NOT NULL,
  "PromisedDate" date NOT NULL,
  "QuotedAtUtc" timestamp with time zone,
  "ReadyAtUtc" timestamp with time zone,
  "Status" character varying(20) NOT NULL,
  "Subtotal" numeric(18,2) NOT NULL,
  "Total" numeric(18,2) NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_Orders_Money" CHECK ("Subtotal" >= 0 AND "Discount" >= 0 AND "Discount" <= "Subtotal" AND "Total" = "Subtotal" - "Discount")
);

CREATE TABLE "OwnershipTransferChallenges" (
  "Id" uuid NOT NULL,
  "BusinessId" uuid NOT NULL,
  "RequestingUserId" uuid NOT NULL,
  "NewOwnerMembershipId" uuid NOT NULL,
  "TokenHash" character varying(64) NOT NULL,
  "ExpiresAtUtc" timestamp with time zone NOT NULL,
  "ConsumedAtUtc" timestamp with time zone,
  "CancelledAtUtc" timestamp with time zone,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  CONSTRAINT "PK_OwnershipTransferChallenges" PRIMARY KEY ("Id")
);

CREATE TABLE "Payments" (
  "Id" uuid NOT NULL,
  "Amount" numeric(18,2) NOT NULL,
  "BusinessId" uuid NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "CurrencyCode" character varying(3) NOT NULL,
  "CustomerId" uuid NOT NULL,
  "IdempotencyKey" character varying(100),
  "InvoiceId" uuid NOT NULL,
  "Method" character varying(20) NOT NULL,
  "Notes" character varying(500),
  "ReceivedOn" date NOT NULL,
  "RecordedByUserId" uuid,
  "Reference" character varying(100),
  "Status" character varying(20) NOT NULL,
  "StatusReason" character varying(500),
  "UpdatedAtUtc" timestamp with time zone,
  "VerifiedAtUtc" timestamp with time zone,
  "VerifiedByUserId" uuid,
  CONSTRAINT "PK_Payments" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_Payments_Amount" CHECK ("Amount" > 0),
  CONSTRAINT "CK_Payments_ReasonWhenClosed" CHECK ("Status" NOT IN ('Rejected','Reversed') OR "StatusReason" IS NOT NULL),
  CONSTRAINT "CK_Payments_VerifiedHasVerifier" CHECK ("Status" <> 'Verified' OR ("VerifiedAtUtc" IS NOT NULL AND "VerifiedByUserId" IS NOT NULL))
);

CREATE TABLE "PlanEntitlements" (
  "PlanId" uuid NOT NULL,
  "Key" character varying(80),
  "Value" character varying(60) NOT NULL,
  CONSTRAINT "PK_PlanEntitlements" PRIMARY KEY ("PlanId", "Key")
);

CREATE TABLE "Plans" (
  "Id" uuid NOT NULL,
  "AnnualPrice" numeric(18,2),
  "Code" character varying(40) NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "CurrencyCode" character varying(3) NOT NULL,
  "Description" character varying(500),
  "IsActive" boolean NOT NULL,
  "MonthlyPrice" numeric(18,2) NOT NULL,
  "Name" character varying(80) NOT NULL,
  "SortOrder" integer NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  CONSTRAINT "PK_Plans" PRIMARY KEY ("Id")
);

CREATE TABLE "PricingProfiles" (
  "Id" uuid NOT NULL,
  "BusinessId" uuid NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "DefaultHourlyRate" numeric(18,2) NOT NULL,
  "Method" character varying(20) NOT NULL,
  "OverheadPercent" numeric(7,2) NOT NULL,
  "RoundingStep" numeric(18,2) NOT NULL,
  "TargetPercent" numeric(7,2) NOT NULL,
  "TaxPercent" numeric(7,2) NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  CONSTRAINT "PK_PricingProfiles" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_PricingProfiles_Ranges" CHECK ("DefaultHourlyRate" >= 0 AND "OverheadPercent" BETWEEN 0 AND 200 AND "TaxPercent" BETWEEN 0 AND 100 AND "RoundingStep" >= 0),
  CONSTRAINT "CK_PricingProfiles_Target" CHECK (("Method" = 'Margin' AND "TargetPercent" BETWEEN 0 AND 95) OR ("Method" = 'Markup' AND "TargetPercent" BETWEEN 0 AND 1000))
);

CREATE TABLE "ProductionTasks" (
  "Id" uuid NOT NULL,
  "ActualStartUtc" timestamp with time zone,
  "AssignedMembershipId" uuid,
  "BlockedReason" character varying(2000),
  "BlockedType" character varying(20),
  "BusinessId" uuid NOT NULL,
  "CancelReason" character varying(500),
  "CompletedAtUtc" timestamp with time zone,
  "CompletionNotes" character varying(2000),
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "CreatedByUserId" uuid,
  "DeadlineUtc" timestamp with time zone,
  "EstimatedMinutes" integer,
  "Instructions" character varying(4000),
  "IsConditional" boolean NOT NULL,
  "OrderGarmentId" uuid NOT NULL,
  "OrderId" uuid NOT NULL,
  "PlannedEndUtc" timestamp with time zone,
  "PlannedStartUtc" timestamp with time zone,
  "Priority" character varying(20) NOT NULL,
  "Quantity" integer NOT NULL,
  "RequiredMaterialsJson" jsonb NOT NULL,
  "RequiredSkill" character varying(60),
  "StageId" uuid,
  "StageName" character varying(80) NOT NULL,
  "StageOrder" integer NOT NULL,
  "Status" character varying(20) NOT NULL,
  "StatusBeforeBlock" character varying(20),
  "Title" character varying(160) NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  "UpdatedByUserId" uuid,
  CONSTRAINT "PK_ProductionTasks" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_ProductionTasks_Dates" CHECK ("CompletedAtUtc" IS NULL OR "Status" = 'Completed'),
  CONSTRAINT "CK_ProductionTasks_Qty" CHECK ("Quantity" > 0 AND ("EstimatedMinutes" IS NULL OR "EstimatedMinutes" > 0))
);

CREATE TABLE "Receipts" (
  "Id" uuid NOT NULL,
  "Amount" numeric(18,2) NOT NULL,
  "BalanceAfter" numeric(18,2) NOT NULL,
  "BusinessId" uuid NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "InvoiceId" uuid NOT NULL,
  "IssuedAtUtc" timestamp with time zone NOT NULL,
  "Number" character varying(30) NOT NULL,
  "PaymentId" uuid NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  "VoidedAtUtc" timestamp with time zone,
  CONSTRAINT "PK_Receipts" PRIMARY KEY ("Id"),
  CONSTRAINT "AK_Receipts_Id_BusinessId" UNIQUE ("Id", "BusinessId"),
  CONSTRAINT "CK_Receipts_Amount" CHECK ("Amount" > 0)
);

CREATE TABLE "RolePermissions" (
  "RoleId" uuid NOT NULL,
