  "UpdatedAtUtc" timestamp with time zone,
  "VersionNumber" integer NOT NULL,
  CONSTRAINT "PK_StorefrontVersions" PRIMARY KEY ("Id")
);

CREATE TABLE "Storefronts" (
  "Id" uuid NOT NULL,
  "Address" character varying(300),
  "AllowSearchIndexing" boolean NOT NULL,
  "BusinessId" uuid NOT NULL,
  "ContactEmail" character varying(120),
  "ContactPhone" character varying(40),
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "DraftJson" text NOT NULL,
  "DraftRevision" integer NOT NULL,
  "Name" character varying(80) NOT NULL,
  "OpeningHours" character varying(300),
  "PublishedVersionId" uuid,
  "Slug" character varying(40) NOT NULL,
  "Status" character varying(20) NOT NULL,
  "TemplateKey" character varying(40) NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  "WorkflowBooking" boolean NOT NULL,
  "WorkflowContact" boolean NOT NULL,
  "WorkflowCustomOrder" boolean NOT NULL,
  "WorkflowInquiry" boolean NOT NULL,
  CONSTRAINT "PK_Storefronts" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_Storefronts_PublishedNeedsVersion" CHECK ("Status" <> 'Published' OR "PublishedVersionId" IS NOT NULL)
);

CREATE TABLE "SubscriptionPayments" (
