);

CREATE TABLE "Subscriptions" (
  "Id" uuid NOT NULL,
  "BusinessId" uuid NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "CurrentPeriodEndUtc" timestamp with time zone,
  "CurrentPeriodStartUtc" timestamp with time zone NOT NULL,
