);

CREATE TABLE "UserSessions" (
  "Id" uuid NOT NULL,
  "AbsoluteExpiresAtUtc" timestamp with time zone NOT NULL,
  "BusinessId" uuid NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "CurrentTokenHash" character varying(64) NOT NULL,
  "DeviceName" character varying(80) NOT NULL,
  "IdleExpiresAtUtc" timestamp with time zone NOT NULL,
  "LastUsedAtUtc" timestamp with time zone NOT NULL,
  "PreviousTokenHash" character varying(64),
  "RevokedAtUtc" timestamp with time zone,
  "RevokedReason" character varying(80),
  "UpdatedAtUtc" timestamp with time zone,
  "UserId" uuid NOT NULL,
  CONSTRAINT "PK_UserSessions" PRIMARY KEY ("Id")
);

CREATE TABLE "WorkerAvailability" (
  "Id" uuid NOT NULL,
  "CapacityMinutes" integer NOT NULL,
  "BusinessId" uuid NOT NULL,
  "DayOfWeek" integer NOT NULL,
  "IsAvailable" boolean NOT NULL,
  "OpensAt" time without time zone,
  "ClosesAt" time without time zone,
  "MembershipId" uuid NOT NULL,
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  CONSTRAINT "PK_WorkerAvailability" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_WorkerAvailability_Day" CHECK ("DayOfWeek" BETWEEN 0 AND 6),
  CONSTRAINT "CK_WorkerAvailability_Window" CHECK (("IsAvailable" = FALSE AND "OpensAt" IS NULL AND "ClosesAt" IS NULL AND "CapacityMinutes" = 0) OR ("IsAvailable" = TRUE AND "OpensAt" IS NOT NULL AND "ClosesAt" IS NOT NULL AND "OpensAt" < "ClosesAt" AND "CapacityMinutes" BETWEEN 1 AND 1440))
);

CREATE TABLE "WorkerLeaves" (
  "Id" uuid NOT NULL,
  "BusinessId" uuid NOT NULL,
  "MembershipId" uuid NOT NULL,
  "StartsAtUtc" timestamp with time zone NOT NULL,
  "EndsAtUtc" timestamp with time zone NOT NULL,
  "Reason" character varying(300) NOT NULL,
  "Status" character varying(20) NOT NULL,
  "CreatedByUserId" uuid,
  "ReviewedByUserId" uuid,
  "ReviewedAtUtc" timestamp with time zone,
  "ReviewNote" character varying(500),
  "CreatedAtUtc" timestamp with time zone NOT NULL,
  "UpdatedAtUtc" timestamp with time zone,
  CONSTRAINT "PK_WorkerLeaves" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_WorkerLeaves_Interval" CHECK ("StartsAtUtc" < "EndsAtUtc")
);

CREATE TABLE "WorkerSkills" (
  "MembershipId" uuid NOT NULL,
  "Skill" character varying(60),
  "BusinessId" uuid NOT NULL,
  CONSTRAINT "PK_WorkerSkills" PRIMARY KEY ("MembershipId", "Skill")
);

CREATE TABLE "Workflows" (
  "Id" uuid NOT NULL,
